drop_ws([C|Cs], Out) :- member(C, [0' , 0'\t, 0'\n, 0'\r]), !, drop_ws(Cs, Out).
drop_ws(Cs, Cs).
raw_text(Kind, Body, [Text]) :-
    atomic_list_concat([Kind, ';\n', Body, '\n'], Text).

